bash --noprofile --norc -e <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

# Find all workflow files under .github/workflows
workflow_files=$(find .github/workflows -type f \( -name "*.yml" -o -name "*.yaml" \) 2>/dev/null || true)

if [ -z "$workflow_files" ]; then
    exit 0
fi

python3 <<'PYEND'
import os, sys, yaml

def is_security_step(step):
    if not isinstance(step, dict):
        return False
    name = step.get('name', '')
    if isinstance(name, str) and 'security' in name.lower():
        return True
    uses = step.get('uses')
    if isinstance(uses, str) and 'security' in uses.lower():
        return True
    return False

violation = False
for root, dirs, files in os.walk('.github/workflows'):
    for f in files:
        if not (f.endswith('.yml') or f.endswith('.yaml')):
            continue
        path = os.path.join(root, f)
        try:
            with open(path, 'r') as fp:
                data = yaml.safe_load(fp)
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        jobs = data.get('jobs')
        if not isinstance(jobs, dict):
            continue
        for job_name, job in jobs.items():
            if not isinstance(job, dict):
                continue
            steps = job.get('steps')
            if not isinstance(steps, list):
                continue
            for step in steps:
                if is_security_step(step):
                    if step.get('continue-on-error') is True:
                        print(f"Violation: {path} job '{job_name}' step '{step.get('name')}' has continue-on-error: true")
                        violation = True
sys.exit(1 if violation else 0)
PYEND
EOF
